41	// Charged on every quote, unconditionally — it is the cost of assessing the
42	// items, not a penalty for being a new customer. Named "first insurance" in
43	// some of the domain material, which misleads: it does not depend on customer
44	// history or on the quote's position in the scenario.
45	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
46	
47	const percentOf = (amount: number, percent: number): number =>
48	  (amount * percent) / 100;
49	
50	const itemBasePremium = (item: Item): number =>
51	  BASE_PREMIUM_BY_TYPE[item.type];
52	
53	const BLOCK_SIZE = 3;
54	
55	const BLOCK_PREMIUM = 60;
56	
57	const sumOf = (amounts: number[]): number =>
58	  amounts.reduce((sum, amount) => sum + amount, 0);
59	
60	const formsABlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;
61	
62	const sumOfItemBasePremiums = (items: Item[]): number =>
63	  sumOf(items.map(itemBasePremium));
64	
65	const groupByType = (items: Item[]): Item[][] => {
66	  const types = new Set(items.map((item) => item.type));
67	
68	  return [...types].map((type) => items.filter((item) => item.type === type));
69	};
70	
71	const alikeGroupBasePremium = (items: Item[]): number =>
72	  formsABlock(items) ? BLOCK_PREMIUM : sumOfItemBasePremiums(items);
73	
74	const policyBasePremium = (items: Item[]): number =>
75	  sumOf(groupByType(items).map(alikeGroupBasePremium));
76	
77	const roundPremiumInMHPCOsFavor = (amount: number): number =>
78	  Math.ceil(amount);
79	
80	// The inputs a single quote is computed from. Today only `items` is consumed;
81	// `customer` is threaded through so policy-wide modifiers that depend on
82	// customer history (loyalty, follow-up contract) have a seat at the table.
83	type QuoteRequest = {
84	  customer: Customer;
85	  items: Item[];
86	};
87	
88	const LOYALTY_YEARS = 2;
89	
90	const LOYALTY_DISCOUNT_PERCENT = 20;
91	
92	// Modifier percents are signed so surcharges and discounts can be summed
93	// uniformly; a discount enters the sum as its negation.
94	const asDiscount = (percent: number): number => -percent;
95	
96	const isLoyal = (customer: Customer): boolean =>
97	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
98	
99	// Policy-wide modifiers do NOT compound: each is an independent percentage of
100	// the policy base premium, and they are summed. Chaining them (base * 1.1 * 0.8)
101	// would give a different, wrong answer.
102	const policyModifierPercents = (request: QuoteRequest): number[] => [
103	  INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
104	  ...(isLoyal(request.customer)
105	    ? [asDiscount(LOYALTY_DISCOUNT_PERCENT)]
106	    : []),
107	];
108	
109	const applyPolicyModifiers = (
110	  basePremium: number,
111	  request: QuoteRequest,
112	): number =>
113	  basePremium +
114	  sumOf(
115	    policyModifierPercents(request).map((percent) =>
116	      percentOf(basePremium, percent),
117	    ),
118	  );
119	
120	const CURSE_SURCHARGE_PERCENT = 50;
121	
122	const HIGH_ENCHANTMENT_LEVEL = 5;
123	
124	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
125	
126	const isHighlyEnchanted = (item: Item): boolean =>
127	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
128	
129	const isCursed = (item: Item): boolean => item.cursed === true;
130	
131	type ItemSurchargeRule = {
132	  applies: (item: Item) => boolean;
133	  percent: number;
134	};
135	
136	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
137	  { applies: isCursed, percent: CURSE_SURCHARGE_PERCENT },
138	  { applies: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
139	];
140	
141	// Item-scoped surcharges are charged on the item's own base premium, so they
142	// must NOT go through applyPolicyModifiers.
143	const itemSurcharges = (item: Item): number =>
144	  sumOf(
145	    ITEM_SURCHARGE_RULES.filter((rule) => rule.applies(item)).map((rule) =>
146	      percentOf(itemBasePremium(item), rule.percent),
147	    ),
148	  );
149	
150	const policyItemSurcharges = (items: Item[]): number =>
151	  sumOf(items.map(itemSurcharges));
152	
153	const quotePremium = (request: QuoteRequest): number =>
154	  roundPremiumInMHPCOsFavor(
155	    applyPolicyModifiers(policyBasePremium(request.items), request) +
156	      policyItemSurcharges(request.items) +
157	      PROCESSING_FEE,
158	  );
159	
160	export const runScenario = (scenario: Scenario): ScenarioResults => ({
161	  results: scenario.steps.map((step) => ({
162	    premium: quotePremium({
163	      customer: scenario.customer,
164	      items: step.items ?? [],
165	    }),
166	  })),
167	});
